import type { ColumnType, Generated } from 'kysely';
import type { DateTime } from 'luxon';

/**
 * Database types.
 *
 * Regenerated by `pnpm build:datatypes` (kysely-codegen) against a migrated database; the checked-in
 * copy exists so a cold clone type-checks before anyone has run Postgres. If the two disagree, the
 * migrations are right and this file is stale.
 */

export interface CardEvents {
    id: Generated<string>;
    project: string;
    cardId: string;
    stage: string | null;
    type: string;
    payload: unknown;
    // KyselyPgTypeOverrides parses timestamptz into a Luxon DateTime, not a JS Date. Declaring it
    // as Date compiles and then fails at runtime on `.toISOString()`, which is exactly how it got
    // past tsc the first time.
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

export interface Cards {
    project: string;
    id: string;
    title: string;
    stage: string;
    branch: string | null;
    /** Current plan text; `CardVersions.body` holds the snapshots. */
    body: string;
    /** Kickback counters keyed by the stage that kicked back. */
    retries: unknown;
    /** External source refs, e.g. `{ linear: 'ENG-123' }`. */
    external: unknown;
    sourceClosed: boolean | null;
    needsHuman: boolean;
    needsHumanReason: string | null;
    /** Orders the parking lot; null elsewhere. */
    position: number | null;
    /** The version downstream stages read. Null until the plan is approved. */
    pinnedVersionId: ColumnType<string | null, string | null | undefined, string | null>;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
    updatedAt: ColumnType<DateTime, DateTime | string | undefined, DateTime | string | undefined>;
}

/**
 * Append-only card history — the replacement for `git log` on the board repo.
 *
 * A version snapshots the whole card, frontmatter and body, because `readAt` used to be
 * `git show <sha>:<path>` and the dispatcher reads frontmatter from the pinned card.
 */
export interface CardVersions {
    id: Generated<string>;
    project: string;
    cardId: string;
    frontmatter: unknown;
    body: string;
    /** What the git commit message used to be. */
    message: string;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * Which job is carrying a card, if any. Operational state: a claim the broker's view of the job id
 * either confirms or retires.
 */
export interface CardJobs {
    project: string;
    cardId: string;
    jobId: string;
    enqueuedAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

export interface CardDeps {
    project: string;
    cardId: string;
    dependsOnId: string;
}

/**
 * Operational settings that can change without a restart — the poller's on/off switch first. One
 * row per (project, key); `SettingsStore` (modules/settings) resolves database row -> environment
 * variable -> coded default. `value` is JSONB so a new setting is a new row, never a new column.
 *
 * Card 0152: `project` is not always a real project name. A setting whose `SettingDefinition.scope`
 * (modules/settings/setting.definition.ts) is `'deployment'` rather than `'project'` is keyed by
 * `SettingsStore`'s reserved `DEPLOYMENT_SCOPE` value instead, so the same row answers regardless of
 * which project is current — no schema change, since `project` was already a plain `TEXT` column.
 */
export interface Settings {
    project: string;
    key: string;
    value: unknown;
    updatedAt: ColumnType<DateTime, DateTime | string | undefined, DateTime | string | undefined>;
}

/**
 * The append-only transcript of a planning conversation — what `PlanTurnRepository` appends to and
 * reads from. `seq` is a monotonic per-(project, card_id) counter, not a timestamp, and is what
 * `Last-Event-ID` replay resumes from. Deliberately not the record of the model's own context; see
 * the migration's header comment for why the two are kept apart.
 */
export interface PlanTurns {
    project: string;
    cardId: string;
    seq: number;
    /** 'user' or 'assistant'. Left as `string` here, like `Cards.stage`, for the same reason: hand-written database types cannot enforce a check constraint. */
    role: string;
    content: string;
    /** The engine's own session id, set on the assistant turn that produced it; null on a user turn. */
    engineSessionId: string | null;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * A comment on a passage of a plan draft — what `PlanCommentRepository` appends to and reads
 * from. `quote`/`prefix`/`suffix` are the anchor exactly as `apps/web/src/lib/anchor.ts`'s
 * `Anchor` captures it, never a stored position; see the migration's header comment for why.
 * `resolved` is a state a comment moves through, not a delete.
 */
export interface PlanComments {
    id: Generated<string>;
    project: string;
    cardId: string;
    quote: string;
    prefix: string;
    suffix: string;
    text: string;
    resolved: boolean;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * A project's identity — the name every other `runner` table's `project` column already carries,
 * plus the three paths `BoardConfig` exposes. `BoardModule.setup` reads this row on boot and seeds
 * it from the environment the first time; see the migration's header comment for what happens
 * when a row exists and the environment disagrees. `board_root` was dropped with the board repo
 * (`20260901130000_drop_board_root.sql`).
 */
export interface Projects {
    name: string;
    codeRoot: string;
    worktreeRoot: string;
    runRoot: string;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * An exclusive claim on a machine-global resource — see the migration
 * (`data/migrations/20260831120000_leases.sql`) for why `resourceKey` alone is the primary key
 * rather than `(project, resourceKey)`.
 */
export interface Leases {
    resourceKey: string;
    project: string;
    cardId: string;
    acquiredAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * A project's stage config — the document that used to be `config/stages.yaml` in the board repo.
 * Append-only; the newest row per project is its current config, and the rest are its history (what
 * `git log` on the file used to be). `StageConfigStore` (modules/stages) reads and writes it.
 */
export interface StageConfigs {
    id: Generated<string>;
    project: string;
    /** The document verbatim, comments included; validated by `parseStages` on every read and write. */
    yaml: string;
    /** What the git commit message on `stages.yaml` used to be. */
    message: string;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * A snapshot of external context attached to a card — what `CardContextRepository` writes to and
 * reads from. `sourceUrl`/`fetchedAt`/`fetchedBy` are the manifest a provider reports about the
 * fetch; `title`/`content`/`contentHash` are what it fetched. See the migration's header comment
 * for why `fetchedAt` and `createdAt` both exist, and why `contentHash` is declared here though
 * nothing reads it yet. Nothing in this table enforces the trimming rule on `content` — that is
 * the provider-seam card's job, not this schema's.
 */
export interface CardContext {
    id: Generated<string>;
    project: string;
    cardId: string;
    sourceUrl: string;
    fetchedAt: ColumnType<DateTime, DateTime | string, never>;
    fetchedBy: string;
    title: string | null;
    content: string;
    contentHash: string;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * Where each card source left off — the cursor `CardSource.changedSince` is handed on the next
 * tick, one row per `(project, source)`. `source` is the same name a ref is stored under in
 * `Cards.external`. A source with no row yet has no cursor: `SourceCursorRepository.get` reports
 * that as `undefined`, which card 0196's interface documents as "since the beginning".
 */
export interface SourceCursors {
    project: string;
    source: string;
    /** Opaque to the board: a timestamp, an ETag or a page token, whatever the source last gave. */
    cursor: string;
    updatedAt: ColumnType<DateTime, DateTime | string | undefined, DateTime | string | undefined>;
}

/**
 * A generic key/value entry with expiry — the table `@maroonedsoftware/cache`'s `CacheProvider` is
 * backed by in this deployment (card 0197). `expires_at` is an absolute point, not a TTL: every
 * `CacheProvider` method already computes one, and storing the deadline directly is what makes both
 * a plain read (`WHERE expiresAt > now()`) and the atomic claim `add` needs (an expired row must
 * read as absent) a comparison rather than a computed one.
 */
export interface CacheEntries {
    key: string;
    value: string;
    expiresAt: ColumnType<DateTime, DateTime | string, DateTime | string>;
}

/**
 * One member of a `CacheProvider` set, the set half of {@link CacheEntries}. A member per row, so
 * two concurrent `setAdd`s to one key each insert their own row instead of racing to rewrite a
 * shared value. `expiresAt` is the whole set's deadline, kept equal across a key's live rows.
 */
export interface CacheSetMembers {
    key: string;
    member: string;
    expiresAt: ColumnType<DateTime, DateTime | string, DateTime | string>;
}

/**
 * The operator account (PROJECT.md decision 10). At most one row, by a unique index on a constant;
 * see the migration.
 */
export interface Accounts {
    id: Generated<string>;
    username: string;
    active: ColumnType<boolean, boolean | undefined, boolean>;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/** The operator account's password, one row per account, as `PasswordFactorRepository` expects. */
export interface AccountPasswords {
    accountId: string;
    hash: string;
    salt: string;
    active: ColumnType<boolean, boolean | undefined, boolean>;
    needsReset: ColumnType<boolean, boolean | undefined, boolean>;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
    updatedAt: ColumnType<DateTime, DateTime | string | undefined, DateTime | string>;
}

/**
 * One of the operator's API keys. Only the token's SHA-256 is stored; see the migration.
 */
export interface ApiKeys {
    id: ColumnType<string, string | undefined, never>;
    accountId: string;
    name: string;
    type: string | null;
    hint: string;
    secretHash: string;
    scopes: string[];
    metadata: ColumnType<Record<string, unknown>, string | undefined, string>;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
    expiresAt: ColumnType<DateTime | null, DateTime | string | null | undefined, DateTime | string | null>;
    lastUsedAt: ColumnType<DateTime | null, DateTime | string | null | undefined, DateTime | string | null>;
    revokedAt: ColumnType<DateTime | null, DateTime | string | null | undefined, DateTime | string | null>;
}

/**
 * An authenticator app (TOTP) enrolled as the operator's second factor. `secret` is the seed,
 * encrypted under the root key; see the migration.
 */
export interface AccountAuthenticators {
    id: ColumnType<string, string | undefined, never>;
    accountId: string;
    secret: string;
    type: string;
    algorithm: string;
    tokenLength: number;
    periodSeconds: number;
    counter: ColumnType<number, number | undefined, number>;
    label: string | null;
    active: ColumnType<boolean, boolean | undefined, boolean>;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

/**
 * A project's human-approved learnings document (card 0239). Append-only, the same shape as
 * {@link StageConfigs}: the newest row per project is the current document and the rest are its
 * history. Agents read it and never write it; an empty `markdown` means "no learnings".
 */
export interface Learnings {
    id: Generated<string>;
    project: string;
    /** The document verbatim. */
    markdown: string;
    /** Why this version was saved — the audit narrative, as on `StageConfigs.message`. */
    message: string;
    createdAt: ColumnType<DateTime, DateTime | string | undefined, never>;
}

export interface DB {
    'runner.cards': Cards;
    'runner.cardVersions': CardVersions;
    'runner.cardDeps': CardDeps;
    'runner.cardJobs': CardJobs;
    'runner.cardEvents': CardEvents;
    'runner.settings': Settings;
    'runner.planTurns': PlanTurns;
    'runner.planComments': PlanComments;
    'runner.projects': Projects;
    'runner.leases': Leases;
    'runner.stageConfigs': StageConfigs;
    'runner.cardContext': CardContext;
    'runner.sourceCursors': SourceCursors;
    'runner.cacheEntries': CacheEntries;
    'runner.cacheSetMembers': CacheSetMembers;
    'runner.accounts': Accounts;
    'runner.accountPasswords': AccountPasswords;
    'runner.apiKeys': ApiKeys;
    'runner.accountAuthenticators': AccountAuthenticators;
    'runner.learnings': Learnings;
}
